<template><div class="page-heading"><div><h1 class="page-title">公众号绑定</h1><p>在此绑定新的微信公众号；保存的密钥会加密保存且不会回显。</p></div></div><div class="content-panel"><el-alert title="绑定前请在微信公众号后台将服务器地址设置为下方回调地址，并填写相同 Token。若使用安全模式，请同时填写 EncodingAESKey。" type="info" :closable="false" show-icon /><el-form label-width="150px" class="form"><el-form-item label="启用公众号功能"><el-switch v-model="form.enabled" /></el-form-item><el-form-item label="公众号 AppID" required><el-input v-model="form.appId" /></el-form-item><el-form-item label="公众号 AppSecret"><el-input v-model="form.appSecret" type="password" show-password :placeholder="status?.hasAppSecret?'已保存，留空不修改':'请输入 AppSecret'" /></el-form-item><el-form-item label="服务器 Token"><el-input v-model="form.token" type="password" show-password :placeholder="status?.hasToken?'已保存，留空不修改':'请输入 Token'" /></el-form-item><el-form-item label="EncodingAESKey"><el-input v-model="form.encodingAesKey" type="password" show-password :placeholder="status?.hasEncodingAesKey?'已保存，留空不修改':'安全模式需要填写'" /></el-form-item><el-form-item label="服务器回调地址"><el-input :model-value="status?.callbackUrl" readonly><template #append><el-button @click="copy">复制</el-button></template></el-input></el-form-item><el-form-item><el-button type="primary" :loading="saving" @click="save">保存并启用</el-button></el-form-item></el-form></div></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import{ElMessage}from'element-plus';import{getOfficialAccountBinding,type OfficialAccountBinding,updateOfficialAccountBinding}from'../api/admin';const status=ref<OfficialAccountBinding|null>(null),saving=ref(false);const form=reactive({enabled:false,appId:'',appSecret:'',token:'',encodingAesKey:''});async function load(){status.value=await getOfficialAccountBinding();form.enabled=status.value.enabled;form.appId=status.value.appId;}async function save(){if(form.enabled&&!form.appId.trim())return ElMessage.warning('请填写公众号 AppID');saving.value=true;try{status.value=await updateOfficialAccountBinding({...form,appId:form.appId.trim()});form.appSecret='';form.token='';form.encodingAesKey='';ElMessage.success('公众号绑定设置已保存');}finally{saving.value=false}}async function copy(){if(status.value?.callbackUrl){await navigator.clipboard.writeText(status.value.callbackUrl);ElMessage.success('回调地址已复制')}}onMounted(load);</script>
<style scoped>.page-heading{margin-bottom:18px}.page-title{margin:0 0 6px}.page-heading p{margin:0;color:var(--admin-text-muted)}.form{max-width:760px;margin-top:24px}</style>
